"use client";

// Retention Strategies — the Phase 7 rule-based review suggestions in the
// Compass visual language. These suggestions are review prompts generated by
// transparent rules, not experimentally proven interventions.

import { useEffect, useState } from "react";
import { LABELS } from "@/lib/chat";
import {
  Filters,
  Portfolio,
  Recommendation,
  filterRows,
  postJson,
  recommendationExportRows,
  saveCsv,
} from "@/lib/portfolio";

export default function RetentionView({
  portfolio,
  filters,
}: {
  portfolio: Portfolio | null;
  filters: Filters;
}) {
  const [recommendations, setRecommendations] = useState<Recommendation[] | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!portfolio) { setRecommendations(null); return; }
    let cancelled = false;
    setBusy(true); setError("");
    const rows = filterRows(portfolio.rows, filters);
    postJson<{ recommendations: Recommendation[] }>("/api/recommend", { rows, thresholds: portfolio.thresholds })
      .then((response) => { if (!cancelled) setRecommendations(response.recommendations); })
      .catch((cause) => { if (!cancelled) setError(cause instanceof Error ? cause.message : "Suggestions could not be generated."); })
      .finally(() => { if (!cancelled) setBusy(false); });
    return () => { cancelled = true; };
  }, [portfolio?.name, portfolio?.rows, filters]);

  if (!portfolio) {
    return <div className="surface panel empty-state">
      <div className="project-icon">✚</div>
      <h2 className="subhead">No customer dataset yet</h2>
      <p className="muted">Load a dataset on the Portfolio page first — suggestions are generated for your actual scored customers, never from sample statistics.</p>
    </div>;
  }

  const byRule = new Map<string, Recommendation[]>();
  for (const item of recommendations ?? []) {
    byRule.set(item.rule_name, [...(byRule.get(item.rule_name) ?? []), item]);
  }
  const customers = new Set((recommendations ?? []).map((item) => item.customer_id));

  return <div className="retention-layout">
    <section className="surface panel">
      <div className="results-head">
        <div>
          <h2 className="subhead">Review suggestions for the current view</h2>
          <p className="section-copy">
            {recommendations === null || busy ? "Generating suggestions…" :
              `${customers.size.toLocaleString()} customer(s) have at least one suggestion, from ${recommendations.length} rule match(es). Filters active: ${filterRows(portfolio.rows, filters).length !== portfolio.rows.length ? "yes" : "no"}.`}
          </p>
        </div>
        <button className="outline-button" disabled={!recommendations?.length} onClick={() => recommendations && saveCsv("cram_retention_recommendations.csv", recommendationExportRows(recommendations))}>↓ Export suggestions</button>
      </div>
      {busy && <div className="progress"><span style={{ width: "70%" }} /></div>}
      {error && <div className="error">{error}</div>}
      <div className="note-card" style={{ marginTop: 6 }}>
        These are rule-based review suggestions for staff follow-up — not proven interventions and not
        guaranteed churn reduction. Each card explains exactly which accepted characteristic triggered it,
        and human approval is always required before contacting a customer.
      </div>
      {recommendations !== null && !busy && byRule.size === 0 &&
        <p className="success-line" style={{ marginTop: 12 }}>No rule thresholds are met in the current view at the active risk bands.</p>}
    </section>

    {[...byRule.entries()].map(([ruleName, items]) => <section className="surface panel" key={ruleName}>
      <div className="results-head">
        <h2 className="subhead">{ruleName}</h2>
        <span className="chip selected">{items.length} customer(s)</span>
      </div>
      <p className="section-copy">{items[0].objective}</p>
      <div className="rec-grid">
        {items.slice(0, 12).map((item, index) => <div className="rec-card" key={item.customer_id + item.rule_id}>
          <div className="rec-head">
            <strong>{item.customer_id}</strong>
            <span className={`risk-pill ${item.priority === "High" ? "high" : "medium"}`}>{item.priority} priority</span>
          </div>
          <p className="section-copy"><b>Why:</b> {item.why_triggered}</p>
          <p className="section-copy"><b>Suggested review:</b> {item.action}</p>
          <div className="profile-label" style={{ marginTop: 8 }}>{item.model_context_status}</div>
          {item.model_context.length > 0 && <div className="section-copy" style={{ fontSize: 10 }}>
            {item.model_context.map((context) => `${LABELS[context.feature] || context.feature} ${context.direction} risk by ${(Math.abs(context.contribution) * 100).toFixed(1)} pt`).join(" · ")}
          </div>}
          <p className="section-copy" style={{ fontSize: 10, color: "#8b9ca4", marginTop: 6 }}>{item.limitations}</p>
          {index === 11 && items.length > 12 ? <p className="section-copy">+ {items.length - 12} more in the export</p> : null}
        </div>)}
      </div>
    </section>)}
  </div>;
}
